e passage from that family to a single\\\\\\\\n   761\\\\\\\\tstrategy of value at least `1 - ε`. Documented in\\\\\\\\n   762\\\\\\\\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex` and issue `#98`.\\\\\\\\n   763\\\\\\\\tElimination: prove an independent finite-dimensional attainment theorem for\\\\\\\\n   764\\\\\\\\t`Game.value` and discharge the `sorry` with it. The source statement is kept\\\\\\\\n   765\\\\\\\\tas printed; it may be weakened only by a future documented statement\\\\\\\\n   766\\\\\\\\tcorrection, not by this proof. -/\\\\\\\\n   767\\\\\\\\ttheorem exists_symmetric_projective_strategy (G : SymmetricGame) (ε : ℝ)\\\\\\\\n   768\\\\\\\\t    (hε : 0 ≤ ε) (h : G.toGame.value = 1 - ε) :\\\\\\\\n   769\\\\\\\\t    ∃ S : SymmetricStrategy G, S.toStrategy.IsProjective ∧\\\\\\\\n   770\\\\\\\\t      1 - ε ≤ S.toStrategy.value := by\\\\\\\\n   771\\\\\\\\t  sorry\\\\\\\\n   772\\\\\\\\t\\\\\\\\n   773\\\\\\\\t/-- Value-preserving formalization-only form of `lem:symmetric-strat` starting\\\\\\\\n   774\\\\\\\\tfrom a specified near-optimal strategy; blueprint\\\\\\\\n   775\\\\\\\\t`ch12_qpbt_games.tex:140-154`, paper `06_nonlocal_games_and_mipstar.tex:94-130`.\\\\\\\\n   776\\\\\\\\tThe source attainment distinction is tracked in\\\\\\\\n   777\\\\\\\\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex`. -/\\\\\\\\n   778\\\\\\\\ttheorem exists_symmetric_projective_strategy_of_strategy (G : SymmetricGame)\\\\\\\\n   779\\\\\\\\t    (ε : ℝ) (S₀ : Strategy G.toGame) (h : 1 - ε ≤ S₀.value) :\\\\\\\\n   780\\\\\\\\t    ∃ S : SymmetricStrategy G, S.toStrategy.IsProjective ∧\\\\\\\\n   781\\\\\\\\t      S.toStrategy.value = S₀.value ∧ 1 - ε ≤ S.toStrategy.value := by\\\\\\\\n   782\\\\\\\\t  have hι := nonempty_of_unit_vector S₀.ψ S₀.ψ_norm\\\\\\\\n   783\\\\\\\\t  letI : Nonempty S₀.ιA := hι.map Prod.fst\\\\\\\\n   784\\\\\\\\t  letI : Nonempty S₀.ιB := hι.map Prod.snd\\\\\\\\n   785\\\\\\\\t  have hq := nonempty_of_probability G.μ G.μ_prob\\\\\\\\n   786\\\\\\\\t  have ha := measurement_outcome_nonempty (S₀.A hq.some.1)\\\\\\\\n   787\\\\\\\\t  let a₀ : G.Answer := Classical.choice ha\\\\\\\\n   788\\\\\\\\t  let T : Strategy G.toGame := projectiveDilation S₀ a₀ a₀\\\\\\\\n   789\\\\\\\\t  let S : SymmetricStrategy G := symmetrizedStrategy T\\\\\\\\n   790\\\\\\\\t  have hT_proj : T.IsProjective := projectiveDilation_isProjective S₀ a₀ a₀\\\\\\\\n   791\\\\\\\\t  have hvalue : S.toStrategy.value = S₀.value := by\\\\\\\\n   792\\\\\\\\t    calc\\\\\\\\n   793\\\\\\\\t      S.toStrategy.value = T.value := symmetrizedStrategy_value T\\\\\\\\n   794\\\\\\\\t      _ = S₀.value := projectiveDilation_value S₀ a₀ a₀\\\\\\\\n   795\\\\\\\\t  exact ⟨S, symmetrizedStrategy_isProjective T hT_proj,\\\\\\\\n   796\\\\\\\\t    hvalue, h.trans_eq hvalue.symm⟩\\\\\\\\n   797\\\\\\\\t\\\\\\\\n   798\\\\\\\\tend\\\\\\\\n   799\\\\\\\\t\\\\\\\\n   800\\\\\\\\tend MIPStarRE.QPBT\\\\\\\\nMIPStarRE/QPBT/Games/StrategyClasses.lean:767:theorem exists_symmetric_projective_strategy (G : SymmetricGame) (ε : ℝ)\\\\\\\\nMIPStarRE/QPBT/Games/StrategyClasses.lean:778:theorem exists_symmetric_projective_strategy_of_strategy (G : SymmetricGame)\\\\\\\\n\\\\\\\",\\\\\\\"exit_code\\\\\\\":0,\\\\\\\"status\\\\\\\":\\\\\\\"completed\\\\\\\"}}\\\\nresults/telemetry/sessions/reviewer-pr184-20260905-04.jsonl-376-{\\\\\\\"type\\\\\\\":\\\\\\\"item.started\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_192\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"nl -ba blueprint/src/chapter/ch12_qpbt_games.tex | sed -n '100,165p'\\\\\\\\nrg -n \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"sorry|admit|native_decide|\\\\\\\\\\\\\\\"'^axiom \\\\\\\\\\\\\\\" MIPStarRE/QPBT/Games/StrategyClasses.lean'\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"\\\\\\\",\\\\\\\"exit_code\\\\\\\":null,\\\\\\\"status\\\\\\\":\\\\\\\"in_progress\\\\\\\"}}\\\\nresults/telemetry/sessions/reviewer-pr184-20260905-04.jsonl-377-{\\\\\\\"type\\\\\\\":\\\\\\\"item.completed\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_192\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"nl -ba blueprint/src/chapter/ch12_qpbt_games.tex | sed -n '100,165p'\\\\\\\\nrg -n \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"sorry|admit|native_decide|\\\\\\\\\\\\\\\"'^axiom \\\\\\\\\\\\\\\" MIPStarRE/QPBT/Games/StrategyClasses.lean'\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"   100\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[Symmetric games and symmetric strategies]\\\\\\\\\\\\\\\\label{def:symmetric-game}\\\\\\\\n   101\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.SymmetricGame, MIPStarRE.QPBT.SymmetricGame.toGame, MIPStarRE.QPBT.SymmetricStrategy, MIPStarRE.QPBT.SymmetricStrategy.toStrategy}\\\\\\\\n   102\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   103\\\\\\\\t\\\\\\\\t% Paper label: rem:symmetric-games (a definition environment carrying a rem: label in the\\\\\\\\n   104\\\\\\\\t\\\\\\\\t% source); relabeled here to match the environment kind.\\\\\\\\n   105\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:game, def:tensor-product-strategy}\\\\\\\\n   106\\\\\\\\t\\\\\\\\tA game $\\\\\\\\\\\\\\\\mathfrak G = (\\\\\\\\\\\\\\\\mathcal X, \\\\\\\\\\\\\\\\mathcal Y, \\\\\\\\\\\\\\\\mathcal A, \\\\\\\\\\\\\\\\mathcal B, \\\\\\\\\\\\\\\\mu, D)$ is \\\\\\\\\\\\\\\\emph{symmetric} if the question and answer alphabets are the same for both players (i.e.\\\\\\\\\\\\\\\\ $\\\\\\\\\\\\\\\\mathcal X = \\\\\\\\\\\\\\\\mathcal Y$ and $\\\\\\\\\\\\\\\\mathcal A = \\\\\\\\\\\\\\\\mathcal B$), the distribution $\\\\\\\\\\\\\\\\mu$ is symmetric (i.e.\\\\\\\\\\\\\\\\ $\\\\\\\\\\\\\\\\mu(x,y) = \\\\\\\\\\\\\\\\mu(y,x)$ for all $x,y$), and the decision predicate $D$ treats both players symmetrically (i.e.\\\\\\\\\\\\\\\\ $D(x,y,a,b) = D(y,x,b,a)$ for all $x,y,a,b$).\\\\\\\\n   107\\\\\\\\t\\\\\\\\n   108\\\\\\\\t\\\\\\\\tA strategy $\\\\\\\\\\\\\\\\mathcal S = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}, A, B)$ is \\\\\\\\\\\\\\\\emph{symmetric} if $\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}$ is a (pure) state in $\\\\\\\\\\\\\\\\mathcal H \\\\\\\\\\\\\\\\ot \\\\\\\\\\\\\\\\mathcal H$, for some Hilbert space $\\\\\\\\\\\\\\\\mathcal H$, that is invariant under permutation of the two factors, and the measurement operators of both players are identical.\\\\\\\\n   109\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n   110\\\\\\\\t\\\\\\\\n   111\\\\\\\\tWe often specify symmetric games $\\\\\\\\\\\\\\\\mathfrak G$ and symmetric strategies $\\\\\\\\\\\\\\\\mathcal S$ using a compact notation: we write $\\\\\\\\\\\\\\\\mathfrak G = (\\\\\\\\\\\\\\\\mathcal X, \\\\\\\\\\\\\\\\mathcal A, \\\\\\\\\\\\\\\\mu, D)$ and $\\\\\\\\\\\\\\\\mathcal S = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}, M)$, where $M$ denotes the set of measurement operators shared by both players.\\\\\\\\n   112\\\\\\\\t\\\\\\\\n   113\\\\\\\\t% Source statement (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:94-99) kept in\\\\\\\\n   114\\\\\\\\t% its original form. The proof below records the approximate form the source argument\\\\\\\\n   115\\\\\\\\t% establishes and leaves the final attainment step unproved; see rem:symmetric-strat-limit.\\\\\\\\n   116\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}[Symmetrization of strategies for symmetric games]\\\\\\\\\\\\\\\\label{lem:symmetric-strat}\\\\\\\\n   117\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy}\\\\\\\\n   118\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}\\\\\\\\n   119\\\\\\\\t\\\\\\\\tLet $\\\\\\\\\\\\\\\\mathfrak G = (\\\\\\\\\\\\\\\\mathcal X, \\\\\\\\\\\\\\\\mathcal A, \\\\\\\\\\\\\\\\mu, D)$ be a symmetric game such that $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G) = 1-\\\\\\\\\\\\\\\\eps$ for some $\\\\\\\\\\\\\\\\eps \\\\\\\\\\\\\\\\ge 0$. Then there exists a symmetric and projective strategy $\\\\\\\\\\\\\\\\mathcal S = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}, M)$ such that $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S) \\\\\\\\\\\\\\\\ge 1-\\\\\\\\\\\\\\\\eps$.\\\\\\\\n   120\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n   121\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n   122\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{thm:naimark}\\\\\\\\n   123\\\\\\\\t\\\\\\\\tThe symmetrization argument establishes the following approximate form of the conclusion: for every $\\\\\\\\\\\\\\\\eps' > \\\\\\\\\\\\\\\\eps$ there exists a symmetric and projective strategy of value at least $1-\\\\\\\\\\\\\\\\eps'$. Indeed, fix $\\\\\\\\\\\\\\\\eps' > \\\\\\\\\\\\\\\\eps$. Since $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G)$ is the supremum of the values of all strategies, there exists a strategy $\\\\\\\\\\\\\\\\mathcal S' = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi'}, A, B)$ with $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S') \\\\\\\\\\\\\\\\ge 1-\\\\\\\\\\\\\\\\eps'$. Using Naimark dilation (Theorem~\\\\\\\\\\\\\\\\ref{thm:naimark}), each dilated sub-measurement being completed to a projective measurement by assigning to one fixed outcome the residual projector of its family --- which changes no correlation on the extended state, as described in Remark~\\\\\\\\\\\\\\\\ref{rem:naimark-for-games} above --- we may assume without loss of generality that $\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi'} \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\C^d_{A'} \\\\\\\\\\\\\\\\ot \\\\\\\\\\\\\\\\C^d_{B'}$ for some integer $d$ and that every $A^x$ and $B^x$ is a projective measurement. Let\\\\\\\\n   124\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n   125\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi} = \\\\\\\\\\\\\\\\frac{1}{\\\\\\\\\\\\\\\\sqrt 2}\\\\\\\\\\\\\\\\, \\\\\\\\\\\\\\\\bigl( \\\\\\\\\\\\\\\\ket{0}_{A}\\\\\\\\\\\\\\\\ket{1}_{B}\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi'}_{A'B'} + \\\\\\\\\\\\\\\\ket{1}_{A}\\\\\\\\\\\\\\\\ket{0}_{B}\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi'_\\\\\\\\\\\\\\\\tau}_{A'B'} \\\\\\\\\\\\\\\\bigr) \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\bigl(\\\\\\\\\\\\\\\\C^2_{A} \\\\\\\\\\\\\\\\ot \\\\\\\\\\\\\\\\C^d_{A'}\\\\\\\\\\\\\\\\bigr) \\\\\\\\\\\\\\\\ot \\\\\\\\\\\\\\\\bigl(\\\\\\\\\\\\\\\\C^2_{B} \\\\\\\\\\\\\\\\ot \\\\\\\\\\\\\\\\C^d_{B'}\\\\\\\\\\\\\\\\bigr)\\\\\\\\\\\\\\\\,,\\\\\\\\n   126\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n   127\\\\\\\\t\\\\\\\\twhere $\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi'_\\\\\\\\\\\\\\\\tau}$ is obtained from $\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi'}$ by permuting the two players' registers; then $\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}$ is invariant under permutation of the register pairs $AA'$ and $BB'$. For each question $x \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\mathcal X$ define the projective measurement $M^x = \\\\\\\\\\\\\\\\{M^x_a\\\\\\\\\\\\\\\\}_{a \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\mathcal A}$ on $\\\\\\\\\\\\\\\\C^2 \\\\\\\\\\\\\\\\ot \\\\\\\\\\\\\\\\C^d$ by\\\\\\\\n   128\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n   129\\\\\\\\t\\\\\\\\t\\\\\\\\tM^x_a = \\\\\\\\\\\\\\\\ket{0}\\\\\\\\\\\\\\\\bra{0} \\\\\\\\\\\\\\\\ot A^x_a + \\\\\\\\\\\\\\\\ket{1}\\\\\\\\\\\\\\\\bra{1} \\\\\\\\\\\\\\\\ot B^x_a\\\\\\\\\\\\\\\\,,\\\\\\\\n   130\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n   131\\\\\\\\t\\\\\\\\tand let each player measure $M$ on their pair of registers. Because the decision predicate $D$ of the symmetric game treats the two players symmetrically, the resulting symmetric projective strategy $\\\\\\\\\\\\\\\\mathcal S = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}, M)$ satisfies $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S) = \\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S') \\\\\\\\\\\\\\\\ge 1-\\\\\\\\\\\\\\\\eps'$. Note that this construction preserves the value of the strategy it is applied to exactly.\\\\\\\\n   132\\\\\\\\t\\\\\\\\n   133\\\\\\\\t\\\\\\\\tThe statement asserts more, namely a single symmetric projective strategy of value at least $1-\\\\\\\\\\\\\\\\eps$ itself. Passing from the family of strategies constructed above to one attaining the bound $1-\\\\\\\\\\\\\\\\eps$ is an attainment step which the argument does not supply: the supremum defining $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G)$ in Definition~\\\\\\\\\\\\\\\\ref{def:tensor-product-value} ranges over strategies of unbounded dimension and need not be attained. This step remains unproved; the obstruction, and the forms of the lemma that the argument does prove, are documented in \\\\\\\\\\\\\\\\cite{gap:qpbt_symmetrization-attainment}. See also Remark~\\\\\\\\\\\\\\\\ref{rem:symmetric-strat-limit}.\\\\\\\\n   134\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n   135\\\\\\\\t\\\\\\\\n   136\\\\\\\\t\\\\\\\\\\\\\\\\begin{remark}[Attainment in the symmetrization lemma]\\\\\\\\\\\\\\\\label{rem:symmetric-strat-limit}\\\\\\\\n   137\\\\\\\\t\\\\\\\\tThe proof of Lemma~\\\\\\\\\\\\\\\\ref{lem:symmetric-strat} yields, for each $\\\\\\\\\\\\\\\\eps' > \\\\\\\\\\\\\\\\eps$, a symmetric projective strategy of value at least $1-\\\\\\\\\\\\\\\\eps'$. The conclusion as stated, at $\\\\\\\\\\\\\\\\eps' = \\\\\\\\\\\\\\\\eps$, does not follow from this: the dilated dimension $d$ may grow as $\\\\\\\\\\\\\\\\eps' \\\\\\\\\\\\\\\\downarrow \\\\\\\\\\\\\\\\eps$, and the supremum defining $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G)$ in Definition~\\\\\\\\\\\\\\\\ref{def:tensor-product-value} need not be attained by any strategy. The symmetrization construction itself is value-preserving, so the conclusion does hold whenever the hypothesis supplies an actual strategy of value at least $1-\\\\\\\\\\\\\\\\eps$ rather than only the value of the game; every use of the lemma in the source proceeds from such a strategy, or from a strict lower bound on the value, and therefore consumes only what the proof establishes. The gap and the available repairs are documented in \\\\\\\\\\\\\\\\cite{gap:qpbt_symmetrization-attainment}.\\\\\\\\n   138\\\\\\\\t\\\\\\\\\\\\\\\\end{remark}\\\\\\\\n   139\\\\\\\\t\\\\\\\\n   140\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}[Formalization support for Lemma~\\\\\\\\\\\\\\\\ref{lem:symmetric-strat}]\\\\\\\\n   141\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\label{lem:symmetric-strat-given-strategy}\\\\\\\\n   142\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy_of_strategy}\\\\\\\\n   143\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   144\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}\\\\\\\\n   145\\\\\\\\t\\\\\\\\tThis formalization-only auxiliary is not a named statement of the paper; it is the value-preserving given-strategy form of Lemma~\\\\\\\\\\\\\\\\ref{lem:symmetric-strat} isolated in Remark~\\\\\\\\\\\\\\\\ref{rem:symmetric-strat-limit}, and it is what the symmetrization argument actually proves. Let $\\\\\\\\\\\\\\\\mathfrak G = (\\\\\\\\\\\\\\\\mathcal X, \\\\\\\\\\\\\\\\mathcal A, \\\\\\\\\\\\\\\\mu, D)$ be a symmetric game and let $\\\\\\\\\\\\\\\\mathcal S'$ be a strategy for $\\\\\\\\\\\\\\\\mathfrak G$ with $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S') \\\\\\\\\\\\\\\\ge 1-\\\\\\\\\\\\\\\\eps$. Then there exists a symmetric and projective strategy $\\\\\\\\\\\\\\\\mathcal S = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}, M)$ with\\\\\\\\n   146\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n   147\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S) = \\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G, \\\\\\\\\\\\\\\\mathcal S') \\\\\\\\\\\\\\\\ge 1-\\\\\\\\\\\\\\\\eps\\\\\\\\\\\\\\\\,.\\\\\\\\n   148\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n   149\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n   150\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n   151\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   152\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{thm:naimark}\\\\\\\\n   153\\\\\\\\t\\\\\\\\tApply Naimark dilation (Theorem~\\\\\\\\\\\\\\\\ref{thm:naimark}) to $\\\\\\\\\\\\\\\\mathcal S'$, completing each dilated family at one fixed outcome as described in Remark~\\\\\\\\\\\\\\\\ref{rem:naimark-for-games}, and then form the permutation-invariant state $\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}$ and the block-diagonal measurements $M^x$ of the proof of Lemma~\\\\\\\\\\\\\\\\ref{lem:symmetric-strat}. Both steps preserve the value of the strategy they are applied to, so $\\\\\\\\\\\\\\\\mathcal S$ has exactly the value of $\\\\\\\\\\\\\\\\mathcal S'$. No attainment step is involved, since the strategy $\\\\\\\\\\\\\\\\mathcal S'$ is given rather than extracted from the supremum defining $\\\\\\\\\\\\\\\\operatorname{val}^*(\\\\\\\\\\\\\\\\mathfrak G)$.\\\\\\\\n   154\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n   155\\\\\\\\t\\\\\\\\n   156\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[Commuting strategies]\\\\\\\\\\\\\\\\label{def:comm-strategy}\\\\\\\\n   157\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.IsCommutingOn, MIPStarRE.QPBT.Strategy.IsCommuting}\\\\\\\\n   158\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   159\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:game, def:tensor-product-strategy}\\\\\\\\n   160\\\\\\\\t\\\\\\\\tLet $\\\\\\\\\\\\\\\\mathfrak G = (\\\\\\\\\\\\\\\\mathcal X, \\\\\\\\\\\\\\\\mathcal Y, \\\\\\\\\\\\\\\\mathcal A, \\\\\\\\\\\\\\\\mathcal B, \\\\\\\\\\\\\\\\mu, D)$ be a game, and let $\\\\\\\\\\\\\\\\mathcal S = (\\\\\\\\\\\\\\\\ket{\\\\\\\\\\\\\\\\psi}, A, B)$ be a strategy for $\\\\\\\\\\\\\\\\mathfrak G$ such that $\\\\\\\\\\\\\\\\mathcal H_A = \\\\\\\\\\\\\\\\mathcal H_B$. We say that $\\\\\\\\\\\\\\\\mathcal S$ is a \\\\\\\\\\\\\\\\emph{commuting strategy for $\\\\\\\\\\\\\\\\mathfrak G$} if for all question pairs $(x,y)$ in the support of $\\\\\\\\\\\\\\\\mu$ (i.e.\\\\\\\\\\\\\\\\ all $(x,y)$ with $\\\\\\\\\\\\\\\\mu(x,y) > 0$) we have\\\\\\\\n   161\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n   162\\\\\\\\t\\\\\\\\t\\\\\\\\t[A^x_a, B^y_b] = 0 \\\\\\\\\\\\\\\\qquad \\\\\\\\\\\\\\\\text{for all } a \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\mathcal A,\\\\\\\\\\\\\\\\ b \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\mathcal B\\\\\\\\\\\\\\\\,,\\\\\\\\n   163\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n   164\\\\\\\\t\\\\\\\\twhere $[A,B] = AB - BA$ denotes the commutator.\\\\\\\\n   165\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n755:**Unfaithful:** The `sorry` is the source's unattested attainment step:\\\\\\\\n764:`Game.value` and discharge the `sorry` with it. The source statement is kept\\\\\\\\n771:  sorry\\\\\\\\n\\\\\\\",\\\\\\\"exit_code\\\\\\\":0,\\\\\\\"status\\\\\\\":\\\\\\\"completed\\\\\\\"}}\\\\nresults/telemetry/sessions/reviewer-pr184-20260905-04.jsonl-378-{\\\\\\\"type\\\\\\\":\\\\\\\"item.started\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_193\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"rg -n -F '\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\eps' references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex | head -n 45\\\\\\\\nnl -ba references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex | sed -n '1,80p;1240,1290p'\\\\\\\\nnl -ba blueprint/src/chapter/ch14_qpbt_observables.tex | sed -n '1,35p;360,430p'\\\\\\\\\\\\\\\"\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"\\\\\\\",\\\\\\\"exit_code\\\\\\\":null,\\\\\\\"status\\\\\\\":\\\\\\\"in_progress\\\\\\\"}}\\\\nresults/telemetry/sessions/reviewer-pr184-20260905-04.jsonl-379-{\\\\\\\"type\\\\\\\":\\\\\\\"item.completed\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_193\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"com